        this.people = people;
        this.claims = claims;
        this.dues = dues;
        this.history = history;
        this.sheets = sheets;
        this.audit = audit;
    }

    /**
     * Take a statement for a person on the sheet, as of a date on or before the sheet's today (null:
     * now). Their claims that counted at the end of that date are bound to the figures they had then,
     * every change made while the sheet's today was after it left out and that date standing in for
     * the sheet's today; every other claim of theirs is left unbound. Refused for a date after the
     * sheet's today, or one the sheet or the person was not yet kept on.
     */
    @Transactional
    public Stated take(String sheetId, String user, long personId, LocalDate asOf) {
        LocalDate today = sheets.today(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        if (asOf != null && asOf.isAfter(today)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A statement cannot be taken as of a date after today.");
        }
        LocalDate day = asOf != null ? asOf : today;
        // On the sheet's today every change counts: the sheet as it stands now. Before it, as kept then.
        Person then;
        // Their claims as they stood then, by id.
        Map<Long, Claim> theirsThen = new LinkedHashMap<>();
        // Everyone's claims and people as they stood then, for the parts of others' claims shared with them.
        Iterable<Claim> allThen;
        Map<Long, Person> peopleThen = new HashMap<>();
        Dues.Basis basis;
        Sheet sheet;
        if (day.equals(today)) {
            then = person;
            claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).forEach(c -> theirsThen.put(c.getId(), c));
            allThen = claims.findBySheetIdOrderByIdDesc(sheetId);
            people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> peopleThen.put(p.getId(), p));
            basis = dues.live(sheetId);
            sheet = sheets.load(sheetId);
        } else {
            SheetHistory.AsOf kept = history.at(sheetId, day).orElseThrow(() -> notYet(day));
            then = kept.people().get(personId);
            if (then == null) {
                throw notYet(day);
            }
            kept.claims().forEach((id, c) -> {
                if (c.getPersonId() == personId) {
                    theirsThen.put(id, c);
                }
            });
            allThen = kept.claims().values();
            peopleThen.putAll(kept.people());
            basis = kept.basis();
            sheet = kept.sheet();
        }
        Rollups.Rollup before = rollups.take(sheetId);
        Map<Long, BigDecimal> bound = new HashMap<>();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean figured = false;
        int counted = 0;
        for (Map.Entry<Long, Claim> entry : theirsThen.entrySet()) {
            Claim claim = entry.getValue();
            // As in the live totals: an OPEN or PENDING claim of a person whose retirement date is reached,
            // and not bound, is left out, as is a claim deferred on the day; a held one counts.
            if (!then.countsLive(claim.getStatus(), claim.isStated(), claim.isDeferredOn(day), day)) {
                continue;
            }
            // The statement binds the due as shown, late charge and floor included: a figure an earlier
            // statement bound stays as it is.
            BigDecimal due = dues.due(claim, then.gradeOn(claim.getDate()), basis);
            figured |= due != null;
            bound.put(entry.getKey(), due);
            counted++;
            if (due != null) {
                // As in the live totals: a shared claim counts its figure less its holders' parts.
                total = total.add(claim.getShares().isEmpty() ? due : due.subtract(claim.sharedPartsOf(due)));
            }
        }
        // As in the live totals: their parts of others' shared claims that count for their own person.
        for (Claim claim : allThen) {
            Person owner = peopleThen.get(claim.getPersonId());
            if (claim.getPersonId() == personId || owner == null || !claim.getStatus().counts()
                    || claim.getShares().stream().noneMatch(share -> share.getPersonId() == personId)
                    || !owner.countsLive(claim.getStatus(), claim.isStated(), claim.isDeferredOn(day), day)) {
                continue;
            }
            BigDecimal figure = dues.due(claim, owner.gradeOn(claim.getDate()), basis);
            if (figure == null) {
                continue;
            }
            figured = true;
            for (var share : claim.getShares()) {
                if (share.getPersonId() == personId) {
                    total = total.add(share.partOf(figure));
                }
            }
        }
        // As on the screen: n/a when the grade in force on the day has no rate, unless a claim has a figure.
        if (basis.rateInForce(then.gradeOn(day), day).isEmpty() && !figured) {
            total = null;
        }
        // A due-total is at most the cap in force on the day. The claims they have now are bound by id.
        total = sheet.capped(total);
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        for (Claim claim : theirs) {
            if (bound.containsKey(claim.getId())) {
                claim.bind(bound.get(claim.getId()));
            } else {
                claim.unbind();
            }
        }
        person.stated(total, day);
        Person saved = people.saveAndFlush(person);
        statements.saveAndFlush(new Statement(sheetId, saved.getId(), saved.getStatementCount(), total, day));
        // The person shows the statement just taken among their lines.
        entities.refresh(saved);
        List<Claim> stated = claims.saveAllAndFlush(theirs);
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " due-total=" + (total != null ? total.toPlainString() : NO_RATE) + " claims=" + counted
                + (asOf != null ? " asof=" + asOf : ""));
        rollups.audit(sheetId, user, before);
        return new Stated(saved, stated);
    }

    /**
     * Hand a person's statements to another they join (on the other's sheet): the other's count
     * becomes their own plus theirs, numbered with theirs first, and the other's last statement stays
     * the other's, or, having none, becomes theirs. The caller saves the other.
     */
    public void handOver(String fromSheetId, Person from, Person into) {
        int moved = from.getStatementCount();
        List<Statement> intos = statements.findBySheetIdAndPersonIdOrderBySeqDesc(into.getSheetId(), into.getId());
        // The other's own are numbered after theirs, the last first so no two share a number.
        for (Statement statement : intos) {
            statement.moveTo(into.getSheetId(), into.getId(), statement.getSeq() + moved);
            statements.saveAndFlush(statement);
        }
        for (Statement statement : statements.findBySheetIdAndPersonIdOrderBySeqDesc(fromSheetId, from.getId())) {
            statement.moveTo(into.getSheetId(), into.getId(), statement.getSeq());
            statements.saveAndFlush(statement);
        }
        into.absorbStatements(from);
    }

    /** Read a saved person again from the store, so they show the statements they now hold. */
    public void reread(Person person) {
        entities.refresh(person);
    }

    /** Move a person's statements with them to the sheet they are now on. */
    public void follow(String fromSheetId, Person person) {
        for (Statement statement : statements.findBySheetIdAndPersonIdOrderBySeqDesc(fromSheetId, person.getId())) {
            statement.moveTo(person.getSheetId(), person.getId(), statement.getSeq());
            statements.saveAndFlush(statement);
        }
    }

    /** Refused: the sheet, or the person, was not yet kept at the end of that date. */
    private static ResponseStatusException notYet(LocalDate day) {
        return new ResponseStatusException(HttpStatus.CONFLICT, "The person was not on the sheet on " + day + ".");
    }

    /**
     * Cancel a person's last statement: the claims it bound are live again (a figure an earlier
     * statement bound is not restored), and the person shows the statement before it, or none. Only a
     * steward cancels; refused when the person has no statement.
     */
    @Transactional
    public Stated cancel(String sheetId, String user, long personId) {
        sheets.lock(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward cancels a statement.");
        }
        if (person.getStatementCount() == 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, person.getName() + " has no statement to cancel.");
        }
        Rollups.Rollup before = rollups.take(sheetId);
        BigDecimal cancelled = person.getStatementTotal();
        List<Statement> taken = statements.findBySheetIdAndPersonIdOrderBySeqDesc(sheetId, personId);
        if (!taken.isEmpty() && taken.get(0).getSeq() == person.getStatementCount()) {
            statements.delete(taken.remove(0));
        }
        // The one before it, when it was recorded.
        Statement previous = taken.isEmpty() || taken.get(0).getSeq() != person.getStatementCount() - 1
                ? null : taken.get(0);
        person.unstated(previous == null ? null : previous.getTotal(), previous == null ? null : previous.getTakenOn());
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        theirs.forEach(Claim::unbind);
        Person saved = people.saveAndFlush(person);
        List<Claim> live = claims.saveAllAndFlush(theirs);
        // The person no longer shows the cancelled statement among their lines.
        entities.refresh(saved);
        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " due-total=" + (cancelled != null ? cancelled.toPlainString() : NO_RATE));
        rollups.audit(sheetId, user, before);
        return new Stated(saved, live);
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status: DRAFT when added; a DRAFT claim may be opened, an OPEN one settled, and a DRAFT,
 * OPEN or PENDING one voided. An OPEN claim a clerk settles above the clerk limit goes PENDING, which
 * a steward approves (SETTLED) or rejects (back to OPEN). A steward may void a SETTLED claim within
 * {@link #VOID_SETTLED_DAYS} days of its settlement; VOID is final. A DRAFT claim may be DELETED, and
 * restored to a DRAFT on the sheet's today it was deleted. A DRAFT opened while its due is above the
 * sheet's review threshold goes to REVIEW instead, which a steward reviews (OPEN) and anyone may void.
 * Only OPEN, PENDING and SETTLED claims count.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** The days after its settlement (by the sheet's today) a SETTLED claim may still be voided. */
    public static final int VOID_SETTLED_DAYS = 7;

    /** Whether a claim may move from this status to {@code next}. */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN, REVIEW -> this == DRAFT;
            case SETTLED, PENDING -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW;
            case DELETED -> this == DRAFT;
            case DRAFT -> this == DELETED;
        };
    }

    /** Whether a claim in this status counts toward what is claimed and due. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether a claim in this status is open: OPEN, or PENDING a steward's approval. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}

