test("deferred bound counts scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "terms", "10");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "cap", "2.00");
  await ui.setSetting(pg_uma, "perm-close", "clerk");
  expect(await ui.addHoliday(pg_uma, "2026-03-13")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "error")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "7.50"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"}));
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "10.35"}));
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  await ui.setSetting(pg_uma, "alert-threshold", "1.00");
  await ui.setSetting(pg_uma, "clerk-limit-B", "0.50");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "terms": "3", "contact": "ADA@X", "tags": "b, a"}));
  expect(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"})).toBeNull();
  expect(await ui.ratePreview(pg_uma, "C", "10.00")).toEqual({ count: 0, diff: "0.00" });
  expect(await ui.pasteClaims(pg_uma, "Ben,3.33,,a, b\nBen,0.40,,a, b")).toBe(2);
  const c_ben_0 = await ui.claimAt(pg_uma, p_ben, 0);
  const c_ben_1 = await ui.claimAt(pg_uma, p_ben, 1);
  expect(await ui.importPeople(pg_uma, "Eve,A")).toMatchObject({"added": 1, "updated": 0});
  const p_eve = await ui.personId(pg_uma, "Eve");
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.transfer(pg_vic, p_ben, `${sheet}-t`)).toBe(true);
  await ui.setToday(pg_vic, "2026-04-07");
  expect(await ui.hold(pg_vic, p_eve, {"from": "2026-02-25"})).toBe(true);
  const c_eve_0 = ui.must(await ui.addClaim(pg_vic, p_eve, {"amount": "25.00", "date": "2026-03-20"}));
  await ui.refresh(pg_vic);
  expect(await ui.statement(pg_vic, p_eve)).toBe(true);
  expect(await ui.claimAction(pg_vic, c_eve_0, "open")).toBe(true);
  expect(await ui.activity(pg_vic)).toEqual(["uma ALERT 1", "uma CLAIM_ADDED 2", "uma CLAIM_OPENED 2", "uma HOLIDAY_ADDED 2", "uma PERSON_ADDED 2", "uma RATE_SET 2", "uma ROLE_SET 1", "uma ROLLUP 4", "uma SETTING_CHANGED 9", "uma TOTALS 2", "uma VOID_REASON_ADDED 2", "vic ALERT 1", "vic CLAIM_ADDED 1", "vic CLAIM_OPENED 1", "vic PERSON_HELD 1", "vic PERSON_TRANSFERRED 1", "vic ROLLUP 1", "vic SNAPSHOT 1", "vic STATEMENT 1", "vic TOTALS 2"]);
  await ui.expectAuditView(pg_vic, "Eve", [
    `ALERT sheet=${sheet} by=vic name=Eve due-total=2.00`,
    `ROLLUP sheet=${sheet} by=vic person=Eve claimed=25.00 due-total=2.00 overdue-total=2.00`,
    `CLAIM_OPENED sheet=${sheet} by=vic person=Eve amount=25.00 date=2026-03-20`,
    `STATEMENT sheet=${sheet} by=vic name=Eve due-total=0.00 claims=0`,
    `CLAIM_ADDED sheet=${sheet} by=vic person=Eve amount=25.00 date=2026-03-20`,
    `PERSON_HELD sheet=${sheet} by=vic name=Eve from=2026-02-25`,
    `SNAPSHOT sheet=${sheet} by=vic name=Eve due-total=0.00`,
    `ROLLUP sheet=${sheet} by=uma person=Eve claimed=0.00 due-total=0.00 overdue-total=0.00`,
    `PERSON_ADDED sheet=${sheet} by=uma name=Eve grade=A`
  ]);
  await ui.refresh(pg_vic);
  expect(await ui.setDueBy(pg_vic, c_eve_0, "2026-03-28")).toBe(true);
  expect(await ui.defer(pg_vic, c_eve_0, "2026-04-24")).toBe(true);
  expect(await ui.setRate(pg_vic, {"grade": "C", "pct": "5.00"})).toBe(true);
  await ui.refresh(pg_vic);
  const c_eve_1 = ui.must(await ui.addClaim(pg_vic, p_eve, {"amount": "4.00", "date": "2026-03-05", "ref": "inv 7", "tags": "a, B"}));
  await ui.refresh(pg_vic);
  expect(await ui.waive(pg_vic, c_eve_0)).toBe(true);
  await ui.refresh(pg_vic);
  expect(await ui.flag(pg_vic, p_eve, "late", "2026-03-12")).toBe(true);
  expect(await ui.claimAction(pg_vic, c_eve_0, "void", "error")).toBe(true);
  expect(await ui.claimAction(pg_vic, c_eve_1, "void", "error")).toBe(true);
  const c_eve_2 = ui.must(await ui.addClaim(pg_vic, p_eve, {"amount": "99.95", "date": "2026-03-05", "ref": "R-2", "tags": "b,a,a"}));
  const c_eve_3 = ui.must(await ui.addClaim(pg_vic, p_eve, {"amount": "0.40", "date": "2026-03-01"}));
  await ui.refresh(pg_vic);

